import{_ as p,a0 as t,w as o,s as d,I as l,x as s,a1 as e,A as i,ao as c}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"初识 Python： global 关键字 | LCTT x X-CMD","titleTemplate":false,"description":"初识 Python： global 关键字 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"初识 Python： global 关键字 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"初识 Python： global 关键字 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180207 Python Global Keyword (With Examples)","title":"初识 Python： global 关键字","tag":"201804","desc":""},"relativePath":"201804/20180207 Python Global Keyword (With Examples).md","filePath":"[post].md"}'),r={name:"201804/20180207 Python Global Keyword (With Examples).md"};function h(g,a,b,k,u,f){const n=t("Link");return o(),d("div",null,[a[16]||(a[16]=l("h1",{id:"初识-python-global-关键字",tabindex:"-1"},[s("初识 Python： global 关键字 "),l("a",{class:"header-anchor",href:"#初识-python-global-关键字","aria-label":"Permalink to “初识 Python： global 关键字”"},"​")],-1)),l("p",null,[a[1]||(a[1]=s("在读这篇文章之前，确保你对 ",-1)),e(n,{href:"https://www.programiz.com/python-programming/global-local-nonlocal-variables"},{default:i(()=>[...a[0]||(a[0]=[s("Python 全局、本地和非本地变量",-1)])]),_:1}),a[2]||(a[2]=s(" 有一定的基础。",-1))]),a[17]||(a[17]=c(`<h3 id="global-关键字简介" tabindex="-1">global 关键字简介 <a class="header-anchor" href="#global-关键字简介" aria-label="Permalink to “global 关键字简介”">​</a></h3><p>在 Python 中，<code>global</code> 关键字允许你修改当前范围之外的变量。它用于创建全局变量并在本地上下文中更改变量。</p><h3 id="global-关键字的规则" tabindex="-1">global 关键字的规则 <a class="header-anchor" href="#global-关键字的规则" aria-label="Permalink to “global 关键字的规则”">​</a></h3><p>在 Python 中，有关 <code>global</code> 关键字基本规则如下：</p><ul><li>当我们在一个函数中创建一个变量时，默认情况下它是本地变量。</li><li>当我们在一个函数之外定义一个变量时，默认情况下它是全局变量。你不必使用 <code>global</code> 关键字。</li><li>我们使用 <code>global</code> 关键字在一个函数中来读写全局变量。</li><li>在一个函数外使用 <code>global</code> 关键字没有效果。</li></ul><h3 id="使用-global-关键字-含示例" tabindex="-1">使用 global 关键字（含示例） <a class="header-anchor" href="#使用-global-关键字-含示例" aria-label="Permalink to “使用  global 关键字（含示例）”">​</a></h3><p>我们来举个例子。</p><h4 id="示例-1-从函数内部访问全局变量" tabindex="-1">示例 1：从函数内部访问全局变量 <a class="header-anchor" href="#示例-1-从函数内部访问全局变量" aria-label="Permalink to “示例 1：从函数内部访问全局变量”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>c = 1 # 全局变量</span></span>
<span class="line"><span>def add():</span></span>
<span class="line"><span>	print(c)</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>add()</span></span></code></pre></div><p>运行程序，输出为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1</span></span></code></pre></div><p>但是我们可能有一些场景需要从函数内部修改全局变量。</p><h4 id="示例-2-在函数内部修改全局变量" tabindex="-1">示例 2：在函数内部修改全局变量 <a class="header-anchor" href="#示例-2-在函数内部修改全局变量" aria-label="Permalink to “示例 2：在函数内部修改全局变量”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>c = 1 # 全局变量</span></span>
<span class="line"><span>def add():</span></span>
<span class="line"><span>	c = c + 2 # 将 c 增加 2</span></span>
<span class="line"><span>	print(c)</span></span>
<span class="line"><span>add()</span></span></code></pre></div><p>运行程序，输出显示错误：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>UnboundLocalError: local variable &#39;c&#39; referenced before assignment</span></span></code></pre></div><p>这是因为在函数中，我们只能访问全局变量但是不能修改它。</p><p>解决的办法是使用 <code>global</code> 关键字。</p><h4 id="示例-3-使用-global-在函数中改变全局变量" tabindex="-1">示例 3：使用 global 在函数中改变全局变量 <a class="header-anchor" href="#示例-3-使用-global-在函数中改变全局变量" aria-label="Permalink to “示例 3：使用 global 在函数中改变全局变量”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>c = 0 # global variable</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>def add():</span></span>
<span class="line"><span>	global c</span></span>
<span class="line"><span>	c = c + 2 # 将 c 增加 2</span></span>
<span class="line"><span>	print(&quot;Inside add():&quot;, c)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>add()</span></span>
<span class="line"><span>print(&quot;In main:&quot;, c)</span></span></code></pre></div><p>运行程序，输出为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Inside add(): 2</span></span>
<span class="line"><span>In main: 2</span></span></code></pre></div><p>在上面的程序中，我们在 <code>add()</code> 函数中定义了 <code>c</code> 将其作为全局关键字。</p><p>然后，我们给变量 <code>c</code> 增加 <code>2</code>，即 <code>c = c + 2</code>。之后，我们调用了 <code>add()</code> 函数。最后，打印全局变量 <code>c</code>。</p><p>正如我们所看到的，在函数外的全局变量也发生了变化，<code>c = 2</code>。</p><h3 id="python-模块中的全局变量" tabindex="-1">Python 模块中的全局变量 <a class="header-anchor" href="#python-模块中的全局变量" aria-label="Permalink to “Python 模块中的全局变量”">​</a></h3><p>在 Python 中，我们创建一个单独的模块 <code>config.py</code> 来保存全局变量并在同一个程序中的 Python 模块之间共享信息。</p><p>以下是如何通过 Python 模块共享全局变量。</p><h4 id="示例-4-在python模块中共享全局变量" tabindex="-1">示例 4：在Python模块中共享全局变量 <a class="header-anchor" href="#示例-4-在python模块中共享全局变量" aria-label="Permalink to “示例 4：在Python模块中共享全局变量”">​</a></h4><p>创建 <code>config.py</code> 文件来存储全局变量</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a = 0</span></span>
<span class="line"><span>b = &quot;empty&quot;</span></span></code></pre></div><p>创建 <code>update.py</code> 文件来改变全局变量</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import config</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>config.a = 10</span></span>
<span class="line"><span>config.b = &quot;alphabet&quot;</span></span></code></pre></div><p>创建 <code>main.py</code> 文件来测试其值的变化</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import config</span></span>
<span class="line"><span>import update</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>print(config.a)</span></span>
<span class="line"><span>print(config.b)</span></span></code></pre></div><p>运行 <code>main.py</code>，输出为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>10</span></span>
<span class="line"><span>alphabet</span></span></code></pre></div><p>在上面，我们创建了三个文件： <code>config.py</code>, <code>update.py</code> 和 <code>main.py</code>。</p><p>在 <code>config.py</code> 模块中保存了全局变量 <code>a</code> 和 <code>b</code>。在 <code>update.py</code> 文件中，我们导入了 <code>config.py</code> 模块并改变了 <code>a</code> 和 <code>b</code> 的值。同样，在 <code>main.py</code> 文件，我们导入了 <code>config.py</code> 和 <code>update.py</code> 模块。最后，我们打印并测试全局变量的值，无论它们是否被改变。</p><h3 id="在嵌套函数中的全局变量" tabindex="-1">在嵌套函数中的全局变量 <a class="header-anchor" href="#在嵌套函数中的全局变量" aria-label="Permalink to “在嵌套函数中的全局变量”">​</a></h3><p>以下是如何在嵌套函数中使用全局变量。</p><h4 id="示例-5-在嵌套函数中使用全局变量" tabindex="-1">示例 5：在嵌套函数中使用全局变量 <a class="header-anchor" href="#示例-5-在嵌套函数中使用全局变量" aria-label="Permalink to “示例 5：在嵌套函数中使用全局变量”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def foo():</span></span>
<span class="line"><span>	x = 20</span></span>
<span class="line"><span>	def bar():</span></span>
<span class="line"><span>		 global x</span></span>
<span class="line"><span>		 x = 25</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>	print(&quot;Before calling bar: &quot;, x)</span></span>
<span class="line"><span>	print(&quot;Calling bar now&quot;)</span></span>
<span class="line"><span>	bar()</span></span>
<span class="line"><span>	print(&quot;After calling bar: &quot;, x)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>foo()</span></span>
<span class="line"><span>print(&quot;x in main : &quot;, x)</span></span></code></pre></div><p>输出为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Before calling bar: 20</span></span>
<span class="line"><span>Calling bar now</span></span>
<span class="line"><span>After calling bar: 20</span></span>
<span class="line"><span>x in main : 25</span></span></code></pre></div><p>在上面的程序中，我们在一个嵌套函数 <code>bar()</code> 中声明了全局变量。在 <code>foo()</code> 函数中， 变量 <code>x</code> 没有全局关键字的作用。</p><p>调用 <code>bar()</code> 之前和之后， 变量 <code>x</code> 取本地变量的值，即 <code>x = 20</code>。在 <code>foo()</code> 函数之外，变量 <code>x</code> 会取在函数 <code>bar()</code> 中的值，即 <code>x = 25</code>。这是因为在 <code>bar()</code> 中，我们对 <code>x</code> 使用 <code>global</code> 关键字创建了一个全局变量（本地范围）。</p><p>如果我们在 <code>bar()</code> 函数内进行了任何修改，那么这些修改就会出现在本地范围之外，即 <code>foo()</code>。</p><hr>`,49)),l("p",null,[a[4]||(a[4]=s("via: ",-1)),e(n,{href:"https://www.programiz.com/python-programming/global-keyword"},{default:i(()=>[...a[3]||(a[3]=[s("https://www.programiz.com/python-programming/global-keyword",-1)])]),_:1})]),l("p",null,[a[8]||(a[8]=s("作者：",-1)),e(n,{href:"https://www.programiz.com"},{default:i(()=>[...a[5]||(a[5]=[s("programiz",-1)])]),_:1}),a[9]||(a[9]=s(" 译者：",-1)),e(n,{href:"https://github.com/MjSeven"},{default:i(()=>[...a[6]||(a[6]=[s("MjSeven",-1)])]),_:1}),a[10]||(a[10]=s(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...a[7]||(a[7]=[s("wxy",-1)])]),_:1})]),l("p",null,[a[13]||(a[13]=s("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[11]||(a[11]=[s("LCTT",-1)])]),_:1}),a[14]||(a[14]=s(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...a[12]||(a[12]=[s("Linux中国",-1)])]),_:1}),a[15]||(a[15]=s(" 荣誉推出",-1))])])}const C=p(r,[["render",h]]);export{x as __pageData,C as default};
